<template>
	<div class="Logoff page">
		<div class="box">
			<div class="cell padding-10 margin-bottom-10">
				<img class="back" @click="go('back')" src="@/assets/img/row-left.png" alt="">
				<div class="title">账号注销</div>
				<div class="back"></div>
			</div>

			<div class="text-center font-color-grey">{{subTitle}}</div>
			<div class="cell">

				<div class="bg-lightgrey border-radius-10  body">
					<p v-html="content"></p>
					<br />

				</div>

			</div>
			<div class="cell">
				<img @click.stop="clickCheck" v-show="checked" class="check" src="@/assets/img/check-red.png" />
				<img @click.stop="clickCheck" v-show="!checked" class="check" src="@/assets/img/uncheck-red.png" />
				<span>&nbsp;&nbsp;</span><span class="text-left">同意并接受游戏注销协议</span>
			</div>
			<div class="foot">
				<div class="btn-box">
					<div class="col-24 padding-6">
						<div class="btn bg-red btn-primary color-white" @click="nextStep">继续注销</div>
					</div>


				</div>
			</div>
		</div>
	</div>
</template>

<script>
	import {
		ref
	} from 'vue'
	export default {
		name: 'Logoff',
		setup() {
			return {
				checked: ref(false),
				subTitle: ref(''),
				content: ref(``),
			}
		},
		async created() {
			let res = await this.$store.dispatch('login/getAgreement', 'closeAccount')
			this.$toast.hide()
			if (this.$check.ok(res)) {
				console.log(res)
				this.content = res[0].data.data.content
				this.subTitle = res[0].data.data.title
			}
		},
		methods: {
			nextStep() {
				if (!this.checked) {
					return this.$toast.show("请勾选协议")
				}
				this.go('/logoffAuth')
			}

		}
	}
</script>
<style scoped>
	.Logoff {
		display: table-cell;
		text-align: center;
		vertical-align: middle;
	}

	.body {
		overflow-y: scroll;
		text-align: left;
		display: block;
		width: 100%;
	}

	.btn {
		text-align: center;
	}

	@media (max-width: 420px) {




		.body {
			height: 200px;
			padding: 20px;
		}

		.btn-box {
			padding: 6px 24px;
			height: 30px;
			margin-bottom: 10px;
		}


	}

	@media (min-width: 420px) {



		.body {
			height: 160px;
			padding: 10px;
		}

		.btn-box {
			padding: 4px 24px;
			height: 24px;
		}


	}
</style>
